<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Document\SnippetVersion\Domain\ValueObject\Holder\SnippetVersionContentTextAttributeHolder;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the SnippetVersionContentTextAttributeHolder trait.
 *
 * Covers assignment, retrieval, default fallback,
 * transfer between holders, validation rules, and unset operations.
 */
class SnippetVersionContentTextAttributeHolderUnitTest extends TestCase
{
    /**
     * Asserts that the code attribute is not assigned by default
     * and that getContentText returns null on a freshly created holder.
     */
    public function testContentTextNotAssignedByDefault(): void
    {
        // Arrange
        $holder = new ImplWithSnippetVersionContentTextAttributeHolderUnitTest();

        // Assert
        $this->assertFalse($holder->isContentTextAssigned());
        $this->assertNull($holder->getContentText());
    }
}
class ImplWithSnippetVersionContentTextAttributeHolderUnitTest
{
    use SnippetVersionContentTextAttributeHolder;
    public function assertRules(ConstraintFailList $errorsList): self
    {
        $result = new self();
        $this->withAssertedContentTextRules($result, $errorsList);
        return $result;
    }

    public function applyDefaults(): void
    {
        $this->withDefaultContentText();
    }
}
